N = {
"d07_a":["McDonald's collected more than ten billion dollars in rent from franchised restaurants in twenty twenty-four.","That happens because franchisees do not just pay royalties for the logo and operating system.","McDonald's generally owns the restaurant land or building, or secures the long-term lease, then charges the franchisee rent.","Its annual filing says conventional franchisees pay rent and royalties tied to sales, with minimum rent requirements.","At the end of a typical franchise term, McDonald's still controls the underlying real estate and can re-franchise the location.","So every successful restaurant can produce food sales, royalties, and rent while the operator handles the kitchen.","The burger brings customers in. Control of the site makes the cash flow unusually durable."],
"d10_a":["Sears helped teach America to shop from home, then entered bankruptcy after shopping moved to screens.","Its famous catalogs connected distant households to an enormous range of merchandise delivered through a national distribution system.","That model reduced the importance of a nearby store: customers could browse at home and order remotely.","But retail shifted again toward e-commerce, faster fulfillment, and competitors built specifically around digital shopping.","Sears still carried the cost and complexity of a huge physical-store network while its core business weakened.","On October fifteenth, twenty eighteen, Sears Holdings filed for Chapter Eleven protection.","The company that mastered remote shopping through paper could not turn that advantage into leadership online."],
"d11_a":["Kodak built the first self-contained digital-camera prototype in nineteen seventy-five, decades before digital photography took over.","Engineer Steven Sasson combined a charge-coupled device, digital memory, and cassette storage into an eight-pound experimental camera.","It captured a low-resolution black-and-white image and needed seconds to record it, but the core idea worked.","Kodak continued developing digital technology, yet its economics remained deeply tied to film, processing, and photographic paper.","As digital cameras improved, every photo taken without film weakened the recurring business Kodak had dominated.","Kodak did sell digital products, but it could not replace the profits disappearing from its old model.","The company filed for Chapter Eleven in twenty twelve. Inventing a transition is not the same as surviving it."],
"d13_a":["Elon Musk's PayPal windfall became fuel for two companies that were both under extreme pressure by two thousand eight.","eBay acquired PayPal in two thousand two for one point five billion dollars, giving Musk a nine-figure payout.","He used much of that fortune to build SpaceX and finance Tesla instead of leaving it in safer assets.","SpaceX suffered three failed launches before its fourth rocket reached orbit in September two thousand eight.","Tesla was also struggling to finance production during the financial crisis and needed another funding round.","Both companies survived that year, but neither outcome was assured when Musk concentrated his capital in them.","The PayPal exit did not end his risk. It financed a much larger one.","One successful company became the bankroll for two uncertain experiments."],
"d13_c":["Debt consolidation can lower one payment while quietly increasing the total amount you pay.","It replaces several debts with one new loan or balance, giving you one due date instead of many.","A genuinely lower rate can reduce interest, but advertised low rates may be temporary or unavailable to weaker borrowers.","A smaller monthly payment can also come from stretching repayment across more years, which may increase total cost.","Fees matter too, and reusing newly cleared credit cards can leave you owing both the new loan and fresh balances.","Consolidation changes the structure of debt. Only the rate, fees, term, and repayment behavior determine whether it saves money."],
"d14_c":["A low lease payment can hide the most important number in the deal: what the car is expected to lose in value.","A purchase loan finances ownership of the vehicle, and the borrower keeps it after the loan is repaid.","A lease mainly charges for depreciation during the lease term, plus a rent charge, taxes, and fees.","The predicted value at the end is called the residual value. A higher residual generally means less depreciation to finance.","Mileage limits, wear charges, and early-termination costs can change the final bill beyond the advertised monthly payment.","When the lease ends, you normally return the car unless the contract offers a purchase option. You paid for use, not ownership."],
"d15_a":["Warby Parker attacked eyewear pricing by removing a layer most customers never saw: the traditional middleman.","Founded in twenty ten, the company began as an online brand selling prescription glasses directly to consumers.","It designed its own frames, controlled its brand, and avoided relying entirely on traditional wholesale distribution.","Its Home Try-On program mailed five frames to customers, solving a basic problem with buying glasses online.","Warby Parker's filing says glasses started at ninety-five dollars, including prescription lenses, using simple unified pricing.","The idea was not merely cheaper frames. It was rebuilding the path from design to customer and keeping control of that relationship."],
"d15_c":["A four-payment checkout plan can feel free to the shopper because the merchant helps fund the system.","Buy now, pay later typically splits a purchase into four installments, with the first payment due at checkout.","CFPB data show merchant discount fees are an important source of provider revenue from these transactions.","Merchants accept the cost because BNPL providers market the service as a way to increase conversion and order size.","Some plans charge late fees, and missed automatic payments can also trigger bank overdraft or insufficient-funds fees.","So zero interest does not mean zero economics. The product shifts revenue toward merchant fees while keeping credit risk with the provider."],
"d16_a":["Airbnb's founders once funded their struggling startup by selling presidential-election cereal for forty dollars a box.","During the two thousand eight campaign, they designed Obama O's and Cap'n McCain's as limited-edition collectibles.","They assembled boxes by hand, filled them with ordinary cereal, and pitched the stunt to political-event crowds.","The sales generated about thirty thousand dollars, according to co-founder Brian Chesky's account of the episode.","Cereal did not prove the home-sharing model, but it supplied cash and demonstrated the founders could create demand from almost nothing.","Investors later used the boxes as evidence of resourcefulness. Before Airbnb scaled rooms, it sold a story in a cereal aisle."],
"d20_a":["BlackBerry's own filings explain its collapse in one sentence: customers wanted products and apps it did not yet have.","The company had built enormous loyalty around secure messaging, enterprise email, and its physical keyboard.","But touchscreen competitors changed expectations around browsers, media, and large app ecosystems.","BlackBerry reported intense U.S. competition, delayed product launches, and no timely high-end LTE offering.","Its next-generation BlackBerry Ten devices arrived after many consumers and developers had already moved to iPhone or Android.","The old strengths never vanished. They simply stopped being enough once the basis of competition changed."],
"d21_a":["Kirkland Signature gives Costco something national brands cannot: a product it controls from shelf price to customer promise.","Costco identifies Kirkland as its private-label brand and says it invests heavily in developing and protecting it.","A private label lets the retailer define specifications, choose suppliers, and sell under a name competitors cannot carry.","That creates a direct comparison on the same shelf: a familiar national brand beside Costco's own alternative.","If members trust Kirkland, Costco can use one brand across groceries, clothing, household goods, and many other categories.","The strategy turns shelf space into an owned asset. Costco is not only choosing products; it is building a brand available only to members."],
"d27_c":["Term and whole life can promise the same death benefit while charging dramatically different premiums because they cover different promises.","Term insurance pays if the insured dies during a specified period, such as ten, twenty, or thirty years.","Most term policies build no cash value, and coverage may end or become more expensive when the term expires.","Whole life is designed to remain in force for life when required premiums are paid, and it builds cash value.","Lifetime coverage and guaranteed cash-value features require the insurer to fund more than a temporary death-risk promise.","That is why term is generally lower-cost coverage for a defined window, while whole life bundles permanent insurance with cash value."],
"d28_a":["A beautiful corner can still be a terrible Starbucks location if traffic, rent, and demand do not work together.","Opening a store commits the company to construction costs, staffing, inventory, and often a long lease.","Starbucks' annual disclosures treat site selection and lease economics as material risks because a weak location is expensive to unwind.","The decision weighs local demand, access, nearby competition, expected sales, operating costs, and whether another store would steal traffic.","That also explains why stores may cluster: nearby locations can serve different traffic patterns or reduce congestion at one busy shop.","The coffee may be standardized, but each address is a capital-allocation decision. A store starts making money before opening only on a spreadsheet."],
"d28_b":["A company can beat last year's profit and still watch its stock fall because the market was expecting even more.","A stock price reflects what buyers and sellers currently believe about future cash flows, risk, and growth.","Before an announcement, forecasts and public information already influence those beliefs and therefore the trading price.","When the result arrives, the surprise matters: good news below expectations can disappoint, while bad news above expectations can bring relief.","That is what traders mean by priced in. The price had already moved in anticipation of a particular outcome.","Markets do not grade a result only against the past. They reprice the gap between what happened and what investors expected."],
"d17_a":["In nineteen eleven, the Supreme Court ordered Standard Oil broken apart under the Sherman Antitrust Act.","The company had grown into a dominant force across refining, transportation, and distribution in the American oil industry.","The Court concluded that its conduct unlawfully restrained trade and ordered the combination dissolved into separate companies.","The breakup did not erase the underlying refineries, pipelines, brands, or shareholders. It separated their corporate control.","Over later decades, successor companies merged and evolved into businesses connected to names including ExxonMobil and Chevron.","One court decision changed ownership boundaries across an industry whose physical assets kept operating for generations."],
"d18_a":["Disney did not create Pixar, Marvel, or Star Wars. It spent about fifteen point five billion dollars to own them.","In two thousand six, Disney agreed to acquire Pixar in an all-stock deal valued around seven point four billion dollars.","In two thousand nine, it announced a roughly four-billion-dollar acquisition of Marvel Entertainment and its character library.","Then in two thousand twelve, Disney agreed to buy Lucasfilm for about four point zero five billion dollars.","Each deal brought proven characters, storytelling teams, and worlds that could extend across films, television, products, and parks.","The strategy reduced the need to invent every franchise internally, but Disney still had to integrate and expand what it bought.","Three acquisitions transformed the creative pipeline by turning outside hits into long-term corporate assets."],
"d25_c":["A HELOC works more like a credit line than a one-time loan, and your house secures every dollar drawn.","Both a home-equity loan and a HELOC let homeowners borrow against equity beyond the first mortgage balance.","A home-equity loan usually delivers one lump sum with a set repayment schedule.","A HELOC provides a reusable line during a draw period: borrow, repay, and potentially borrow again.","Many HELOCs have variable rates, so required payments can change as benchmark rates move.","The flexibility does not reduce the collateral risk. Failure to repay can lead to foreclosure because the home secures the account.","One delivers cash once; the other keeps a credit line open. Both convert home equity into debt."],
"d26_c":["Identity-theft monitoring cannot stop your personal information from being stolen. It can only warn you when misuse appears.","Monitoring services watch credit files or accounts for changes such as new inquiries, accounts, or exposed credentials.","Those alerts can shorten response time, but they usually arrive after data was exposed or someone attempted a transaction.","A credit freeze does a different job: it restricts access to your credit file, making many new-account approvals harder.","Federal law makes freezes free to place and lift with each nationwide credit bureau.","Monitoring is an alarm. A freeze is a lock on one door. Neither covers every kind of identity fraud, but they are not interchangeable."],
}

HOOKS={k:v[0] for k,v in N.items()}
for jid, narr in N.items():
    gp=J/f"{jid}.scene.json"; mp=J/f"{jid}.meta.json"
    g=json.loads(gp.read_text(encoding="utf-8")); m=json.loads(mp.read_text(encoding="utf-8"))
    assert len(g["scenes"])==len(narr),(jid,len(g["scenes"]),len(narr))
    for s,text in zip(g["scenes"],narr): s["narration"]=text
    g["meta"]["hook"]=HOOKS[jid]
    m["sources"]=SOURCES[jid]
    m["quality_scores"]={"hook":8,"clarity":9,"retention":8,"fact_confidence":9,"visual_potential":8,"us_relevance":9,"originality":8,"average":8.43}
    m["rewritten"]=True
    m["status"]="READY"
    gp.write_text(json.dumps(g,indent=2),encoding="utf-8");mp.write_text(json.dumps(m,indent=2),encoding="utf-8")

# Pacing is driven by both narration and declared scene timing. Retiming to a
# conservative ~145 spoken words/minute keeps every revised job inside 35-55s.
for jid in N:
    gp=J/f"{jid}.scene.json";g=json.loads(gp.read_text(encoding="utf-8"))
    wc=sum(len(re.findall(r"\b[\w'-]+\b",s["narration"])) for s in g["scenes"])
    target=max(35.0,min(55.0,wc/2.42))
    per=target/len(g["scenes"])
    for s in g["scenes"]:s["duration_sec"]=round(per,2)
    gp.write_text(json.dumps(g,indent=2),encoding="utf-8")

print("fixed",len(N),"documented exceptions")
